// HAOpen opens a live [HAStream] on a warm-up history, oldest bar first, and
// returns it with its values at the last history bar (outHAOpen, outHAHigh,
// outHALow and outHAClose), the values [Core.HA] writes there.
//
// inOpen, inHigh, inLow and inClose are the histories, of one length.
//
// The error is [InsufficientHistory] for a history of at most [Core.HALookback]
// bars, and [BadParam] for histories of different lengths.
func (c *Core) HAOpen(inOpen, inHigh, inLow, inClose []float64) (*HAStream, float64, float64, float64, float64, error) {
	sp, err := c.haOpenInternal(inOpen, inHigh, inLow, inClose, 0)
	if err != nil {
		return nil, 0, 0, 0, 0, err
	}
	return sp, sp.cur_outHAOpen, sp.cur_outHAHigh, sp.cur_outHALow, sp.cur_outHAClose, nil
}

